  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, which shares the sulfonylurea-cyclohexyl and phenethyl linker core with the query, has an absolute oral bioavailability of 97% in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tolbutamide, a sulfonylurea oral antidiabetic, has an oral bioavailability of 93% in humans, supporting high F for this sulfonylurea-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Levosulpiride, a structurally related sulfonamide benzamide, has an absolute oral bioavailability of 23.4%, which is above the 20% threshold and therefore supports a high classification, though with lower transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Amisulpride, a related substituted benzamide, has an absolute bioavailability of approximately 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Metoclopramide, a substituted benzamide with similar aromatic substitution, has an oral bioavailability of about 68%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Veralipride, a sulfonamide-substituted benzamide, has an absolute bioavailability of about 79%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Flecainide, a benzamide with similar ether/aromatic features, has an oral bioavailability of about 95%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Avanafil has a low oral bioavailability of 8–10%, but it is structurally distant and from a different drug class, providing only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfonylurea-cyclohexyl analogue closely related to glimepiride, whose absolute oral bioavailability is ~97–100%. Additional sulfonylurea and benzamide analogues mostly show F well above the 20% threshold. Only a distant, low-F analogue (avanafil) contradicts, but with low transferability. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact query molecule; the prediction relies on close analogues.",
    "The specific effect of the 2-methoxy-5-chlorobenzoyl substitution on absorption, efflux, or first-pass metabolism is not experimentally characterized.",
    "No formulation-specific or solubility data are available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

